// ═══════════════════════════════════════════════════════
// Validate — GENERATED by scripts/sync-init-data-verification.mjs
// Edit n8n/templates/verify-init-data.js and re-run this script.
// ═══════════════════════════════════════════════════════

// initData HMAC verification (mirror: n8n/templates/verify-init-data.js)
/**
 * verify-init-data.js
 * n8n Code Node — verifies the signed Telegram WebApp `initData` string.
 *
 * Implements Telegram's official Mini App validation algorithm (NOT the
 * separate Login Widget algorithm, which uses a different secret derivation):
 *   secret_key = HMAC_SHA256(key="WebAppData", message=bot_token)
 *   hash       = HMAC_SHA256(key=secret_key,    message=data_check_string)
 * where data_check_string is every received field except `hash`, formatted
 * as "key=value" lines sorted alphabetically by key and joined with "\n".
 *
 * Without this check, a client can send an arbitrary `user_id` (#56) and
 * have a document generated/sent under someone else's identity.
 *
 * Query string is parsed by hand (split/decodeURIComponent) instead of the
 * `URLSearchParams` global — n8n's Code node sandbox does not expose it
 * (confirmed live: `ReferenceError: URLSearchParams is not defined`), even
 * though `require('crypto')` and `Buffer` are available.
 *
 * n8n entry point (paste into Code Node):
 *   const botToken = $('Global Config').first().json.TELEGRAM_BOT_TOKEN;
 *   const result = verifyInitData($('Webhook').first().json.body.init_data, botToken);
 *   return [{ json: result }];
 */

const crypto = require('crypto');

function parseQueryString(qs) {
  const out = {};
  for (const pair of qs.split('&')) {
    if (!pair) continue;
    const eq = pair.indexOf('=');
    const rawKey = eq === -1 ? pair : pair.slice(0, eq);
    const rawValue = eq === -1 ? '' : pair.slice(eq + 1);
    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const value = decodeURIComponent(rawValue.replace(/\+/g, ' '));
    out[key] = value;
  }
  return out;
}

/**
 * @param {string} initData - raw `Telegram.WebApp.initData` query string
 * @param {string} botToken - the bot's token (secret)
 * @param {{ maxAgeSeconds?: number }} [options] - maxAgeSeconds: replay window, default 24h
 * @returns {{ valid: boolean, reason?: string, user?: { id: number, first_name?: string, [k: string]: any } }}
 */
function verifyInitData(initData, botToken, options) {
  const maxAgeSeconds = options && options.maxAgeSeconds != null ? options.maxAgeSeconds : 86400;

  if (!initData) return { valid: false, reason: 'missing' };
  if (!botToken) return { valid: false, reason: 'no_bot_token' };

  let params;
  try {
    params = parseQueryString(initData);
  } catch (_) {
    return { valid: false, reason: 'malformed' };
  }

  const hash = params.hash;
  if (!hash) return { valid: false, reason: 'missing_hash' };

  const pairs = [];
  for (const key of Object.keys(params)) {
    if (key === 'hash') continue;
    pairs.push(key + '=' + params[key]);
  }
  pairs.sort();
  const dataCheckString = pairs.join('\n');

  const secretKey = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
  const computedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');

  const computedBuf = Buffer.from(computedHash, 'hex');
  const givenBuf = Buffer.from(hash, 'hex');
  if (computedBuf.length !== givenBuf.length || !crypto.timingSafeEqual(computedBuf, givenBuf)) {
    return { valid: false, reason: 'bad_signature' };
  }

  const authDate = Number(params.auth_date);
  if (!authDate) return { valid: false, reason: 'missing_auth_date' };
  const ageSeconds = Date.now() / 1000 - authDate;
  if (ageSeconds > maxAgeSeconds) return { valid: false, reason: 'expired' };

  const userRaw = params.user;
  let user = null;
  if (userRaw) {
    try {
      user = JSON.parse(userRaw);
    } catch (_) {
      return { valid: false, reason: 'malformed_user' };
    }
  }
  if (!user || !user.id) return { valid: false, reason: 'missing_user' };

  return { valid: true, user };
}

// ── Exports (for Node.js testing; ignored in n8n Code Node) ────────────────

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { verifyInitData };
}


// n8n entry point:
const body = $('Webhook').first().json.body;
const { service_slug, user_id, answers, consented_at, init_data } = body;

if (!user_id) return [{ json: { _valid: false, _error: 'missing user_id' } }];
if (!service_slug) return [{ json: { _valid: false, _error: 'missing service_slug' } }];
if (!answers || Object.keys(answers).length === 0) return [{ json: { _valid: false, _error: 'empty answers' } }];

const botToken = $('Global Config').first().json.TELEGRAM_BOT_TOKEN;
let resolvedUserId = String(user_id);
let uidVerified = false;

if (init_data) {
  const verification = verifyInitData(init_data, botToken);
  if (!verification.valid) {
    console.log('[Validate] init_data verification failed:', verification.reason);
    return [{ json: { _valid: false, _error: 'invalid_init_data' } }];
  }
  resolvedUserId = String(verification.user.id);
  uidVerified = true;
}
// else: no init_data — dev/web-fallback path (#56), accept but mark unverified.

return [{ json: {
  _valid: true,
  _user_id: resolvedUserId,
  _uid_verified: uidVerified,
  _service_slug: service_slug,
  _answers: answers,
  _consented_at: consented_at || new Date().toISOString(),
  _submitted_at: new Date().toISOString()
}}];

const rows = $('Get Service').all();
const svc = rows.length ? rows[0].json : null;
const UNAVAILABLE = 'На жаль, ця послуга зараз тимчасово недоступна. Ми оновлюємо її відповідно до змін у законодавстві. Спробуйте, будь ласка, пізніше.';
const NOT_FOUND = 'На жаль, цю послугу не знайдено або вона недоступна. Спробуйте, будь ласка, пізніше.';
let out;
if (!svc) {
  out = { _active: false, _status: 'not_found', _service_title: null, _block_message: NOT_FOUND };
} else if (svc.status === 'active') {
  out = { _active: true, _status: 'active', _service_title: svc.title || null, _block_message: null };
} else {
  out = { _active: false, _status: svc.status || 'unknown', _service_title: svc.title || null, _block_message: UNAVAILABLE };
}
return [{ json: out }];

// ═══════════════════════════════════════════════════════
// Encrypt Data — AES-256-GCM шифрування PII перед збереженням
// Формат: v1:<iv_hex>:<authTag_hex>:<ciphertext_hex>
// ═══════════════════════════════════════════════════════
const crypto = require('crypto');

const key = Buffer.from($('Global Config').first().json.ENCRYPTION_KEY, 'hex');
const plaintext = JSON.stringify($('Validate').first().json._answers);

const iv = crypto.randomBytes(12);
const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

let encrypted = cipher.update(plaintext, 'utf8', 'hex');
encrypted += cipher.final('hex');
const authTag = cipher.getAuthTag().toString('hex');

const result = 'v1:' + iv.toString('hex') + ':' + authTag + ':' + encrypted;
console.log('[Encrypt] Data encrypted, length:', result.length);

return [{ json: {
  _encrypted_data: result,
  _answers: $('Validate').first().json._answers
}}];

const answers = $('Validate').item.json._answers || {};
const serviceSlug = $('Validate').item.json._service_slug || 'divorce';

const plaintiffName = [answers.last_name, answers.first_name, answers.middle_name].filter(Boolean).join(' ');

// divorce: spouse_*, alimony: defendant_* — handle both
const defLast   = answers.defendant_last_name   || answers.spouse_last_name   || '';
const defFirst  = answers.defendant_first_name  || answers.spouse_first_name  || '';
const defMiddle = answers.defendant_middle_name || answers.spouse_middle_name || '';
const defendantName = [defLast, defFirst, defMiddle].filter(Boolean).join(' ');

const marriagePlace = answers.marriage_place || '';

// Extract children (alimony has cert info after 3rd comma — strip it)
let childrenLine = '';
if (answers.children_details) {
  childrenLine = String(answers.children_details).split('\n')
    .map(line => {
      const parts = line.split(/,\s*/);
      return [parts[0], parts[1]].filter(Boolean).join(', ');
    })
    .filter(Boolean).join('; ');
}

const serviceLabel = serviceSlug === 'alimony' ? 'аліменти' : 'розлучення';
let prompt = 'Ти — помічник для відмінювання українських ПІБ та назв установ для позову про ' + serviceLabel + '. Відповідай ТІЛЬКИ JSON, без markdown, без пояснень.\r\n\r\nОтримані дані:\r\nПозивач: ' + plaintiffName + '\r\nВідповідач: ' + defendantName + '\r\n';
if (marriagePlace) prompt += 'Місце реєстрації шлюбу: ' + marriagePlace + '\r\n';
if (childrenLine)  prompt += 'Діти: ' + childrenLine + '\r\n';

prompt += '\r\nПоверни JSON з 6 полями:\r\n- plaintiff_instrumental: ПІБ позивача в орудному відмінку\r\n- plaintiff_genitive: ПІБ позивача в родовому відмінку\r\n- defendant_instrumental: ПІБ відповідача в орудному відмінку (уклали шлюб з ким? або стосунки з ким?)\r\n- defendant_genitive: ПІБ відповідача в родовому відмінку (стягнути з кого?)\r\n- marriage_place_locative: назва установи в місцевому відмінку — null якщо немає\r\n- children_genitive: ПІБ дітей в родовому відмінку з датами "ПІБ, дата р.н." через "; " — null якщо немає\r\n\r\nПриклад:\r\nВхід: Іванова Інна Петрівна / Іванов Іван Іванович / Шевченківський відділ РАЦС у м. Києві / Іванов Олег Іванович, 15.05.2018\r\nВихід: {"plaintiff_instrumental":"Іванову Інну Петрівну","plaintiff_genitive":"Іванової Інни Петрівни","defendant_instrumental":"Івановим Іваном Івановичем","defendant_genitive":"Іванова Івана Івановича","marriage_place_locative":"Шевченківському відділі РАЦС у м. Києві","children_genitive":"Іванова Олега Івановича, 15.05.2018 р.н."}\r\n';

console.log('[Declension] service:', serviceSlug, '| plaintiff:', plaintiffName, '| defendant:', defendantName);

return [{ json: {
  model: 'llama-3.3-70b-versatile',
  max_tokens: 400,
  temperature: 0,
  messages: [
    { role: 'system', content: prompt },
    { role: 'user', content: 'Відміни вказані дані. Поверни ТІЛЬКИ JSON.' }
  ]
}}];

// ═══════════════════════════════════════════════════════
// Build Document — GENERATED by scripts/sync-build-document-node.mjs
// Do NOT edit inline: edit the mirrors in n8n/templates/ and re-run the script.
// ═══════════════════════════════════════════════════════

// 1. Parse AI declension
let ai = {};
try {
  const raw = $('AI Declension').item.json?.choices?.[0]?.message?.content || '{}';
  const cleaned = raw.replace(/```json?\n?/g, '').replace(/`/g, '').trim();
  ai = JSON.parse(cleaned);
  console.log('[Build] AI parsed OK:', Object.keys(ai).join(', '));
} catch (e) {
  console.log('[Build] AI parse failed, using fallbacks:', e.message);
}

// 2. Service data
const serviceSlug = $('Validate').item.json._service_slug || 'divorce';
const answers = $('Validate').item.json._answers || {};
const caseId = $('Insert Case').item.json.id;
const svc = $('Get Service').first().json || {};

// 3. Shared render engine (mirror: n8n/templates/render-document.js)
/**
 * render-document.js
 * n8n Code Node — service-agnostic document render engine (doc-engine, #34).
 *
 * Renders a declarative template (stored in services.document_template) against
 * the form answers + AI declensions. The template is DATA edited by a lawyer;
 * this engine is the only CODE — written once, tested once, shared by all
 * template-mode services.
 *
 * DSL contract (specs/features/doc-engine/requirements.md §3):
 *   {{field}}                  interpolation; empty → '________' fallback
 *   {{field|raw}}              interpolation without fallback
 *   {{helper arg 'lit' 42}}    helper call (registered helpers only)
 *   {{#if expr}} {{else if expr}} {{else}} {{/if}}
 *       expr: truthiness | == != > < >= <= | and / or / not (flat chains)
 *   {{#each path}} ... {{/each}}   with {{@index1}} {{@first}} {{@last}}
 *   {{! comment }}             dropped from output
 *   {{!style: ...}}            phase-2 paragraph style directive — IGNORED in
 *                              phase 1 (reserved: right center bold indent
 *                              keep-with-next keep-together page-break-before)
 *
 * Block tags / comments standing alone on a line consume that line (so the
 * template reads like the document and output stays byte-exact).
 *
 * SECURITY: pure parser — no eval / new Function. A lawyer-edited template
 * cannot execute code inside n8n.
 *
 * n8n entry point (inside Build Document node):
 *   const context = buildContext(answers, ai);
 *   const document = renderDocument(svc.document_template, context);
 */

const FALLBACK = '________';

// ─── Tokenizer ───────────────────────────────────────────────────────────────

const TAG_RE = /\{\{([\s\S]*?)\}\}/g;

function tokenize(template) {
  const tokens = [];
  let last = 0;
  let m;
  TAG_RE.lastIndex = 0;
  while ((m = TAG_RE.exec(template)) !== null) {
    if (m.index > last) tokens.push({ type: 'text', value: template.slice(last, m.index) });
    const line = template.slice(0, m.index).split('\n').length;
    tokens.push({ type: 'tag', content: m[1].trim(), line });
    last = TAG_RE.lastIndex;
  }
  if (last < template.length) tokens.push({ type: 'text', value: template.slice(last) });
  return tokens;
}

function classifyTag(content) {
  if (content.startsWith('!style:')) return 'style';
  if (content.startsWith('!')) return 'comment';
  if (content.startsWith('#if ')) return 'if';
  if (content === 'else') return 'else';
  if (content.startsWith('else if ')) return 'elseif';
  if (content === '/if') return 'endif';
  if (content.startsWith('#each ')) return 'each';
  if (content === '/each') return 'endeach';
  return 'interp';
}

/**
 * Mustache-style standalone handling: a non-interpolation tag alone on its
 * line swallows the line (leading indent + trailing newline). Detection runs
 * on the ORIGINAL text so adjacent standalone tags don't double-consume.
 */
function applyStandalone(tokens) {
  const standalone = tokens.map((t, i) => {
    if (t.type !== 'tag' || classifyTag(t.content) === 'interp') return false;
    // 'style' directives are standalone (same rule as other block tags)
    const prev = tokens[i - 1];
    const next = tokens[i + 1];
    const prevOk = !prev || (prev.type === 'text' && /(^|\n)[ \t]*$/.test(prev.value));
    const nextOk = !next || (next.type === 'text' && /^[ \t]*(\n|$)/.test(next.value));
    return prevOk && nextOk;
  });
  tokens.forEach((t, i) => {
    if (!standalone[i]) return;
    const prev = tokens[i - 1];
    const next = tokens[i + 1];
    if (prev && prev.type === 'text') prev.value = prev.value.replace(/[ \t]+$/, '');
    if (next && next.type === 'text') next.value = next.value.replace(/^[ \t]*\n/, '');
  });
  return tokens;
}

// ─── Argument / expression tokenizer ─────────────────────────────────────────

/** Split tag content into words and 'quoted literals' (literals may hold spaces). */
function splitArgs(s, line) {
  const out = [];
  let i = 0;
  while (i < s.length) {
    if (/\s/.test(s[i])) { i++; continue; }
    if (s[i] === "'") {
      const end = s.indexOf("'", i + 1);
      if (end === -1) throw new Error(`Unterminated string literal in "{{${s}}}" at line ${line}`);
      out.push({ kind: 'lit', value: s.slice(i + 1, end) });
      i = end + 1;
    } else {
      let j = i;
      while (j < s.length && !/\s/.test(s[j])) j++;
      out.push({ kind: 'word', value: s.slice(i, j) });
      i = j;
    }
  }
  return out;
}

const NUM_RE = /^-?\d+(\.\d+)?$/;

function toOperand(tok) {
  if (tok.kind === 'lit') return { op: 'lit', value: tok.value };
  if (NUM_RE.test(tok.value)) return { op: 'num', value: Number(tok.value) };
  return { op: 'path', value: tok.value };
}

const CMP_OPS = ['==', '!=', '>=', '<=', '>', '<'];

/** Recursive-descent boolean expression parser: or → and → not → cmp → value. */
function parseExpr(src, line) {
  const toks = splitArgs(src, line);
  let p = 0;
  const isWord = (v) => p < toks.length && toks[p].kind === 'word' && toks[p].value === v;

  function parseOr() {
    let left = parseAnd();
    while (isWord('or')) { p++; left = { op: 'or', left, right: parseAnd() }; }
    return left;
  }
  function parseAnd() {
    let left = parseNot();
    while (isWord('and')) { p++; left = { op: 'and', left, right: parseNot() }; }
    return left;
  }
  function parseNot() {
    if (isWord('not')) { p++; return { op: 'not', operand: parseNot() }; }
    return parseCmp();
  }
  function parseCmp() {
    const left = parseValue();
    if (p < toks.length && toks[p].kind === 'word' && CMP_OPS.includes(toks[p].value)) {
      const op = toks[p].value;
      p++;
      return { op, left, right: parseValue() };
    }
    return { op: 'truthy', operand: left };
  }
  function parseValue() {
    if (p >= toks.length) throw new Error(`Incomplete expression "${src}" at line ${line}`);
    const t = toks[p];
    if (t.kind === 'word' && (CMP_OPS.includes(t.value) || ['and', 'or', 'not'].includes(t.value))) {
      throw new Error(`Unexpected "${t.value}" in expression "${src}" at line ${line}`);
    }
    p++;
    return toOperand(t);
  }

  const ast = parseOr();
  if (p < toks.length) throw new Error(`Unexpected "${toks[p].value}" in expression "${src}" at line ${line}`);
  return ast;
}

// ─── Parser ──────────────────────────────────────────────────────────────────

function parseTemplate(template) {
  const tokens = applyStandalone(tokenize(String(template).replace(/\r\n/g, '\n')));
  let pos = 0;

  function peekKind() {
    const t = tokens[pos];
    return t && t.type === 'tag' ? classifyTag(t.content) : null;
  }

  function parseInterp(t) {
    let content = t.content;
    let raw = false;
    const rawMatch = content.match(/^(.*?)\s*\|\s*raw$/);
    if (rawMatch) { content = rawMatch[1].trim(); raw = true; }
    const parts = splitArgs(content, t.line);
    if (parts.length === 0) throw new Error(`Empty tag {{}} at line ${t.line}`);
    if (parts.length > 1) {
      const name = parts[0].value;
      if (parts[0].kind !== 'word' || !HELPERS[name]) {
        throw new Error(`Unknown helper "${name}" at line ${t.line}`);
      }
      return { type: 'helper', name, args: parts.slice(1).map(toOperand), line: t.line };
    }
    if (parts[0].kind === 'lit') return { type: 'text', value: parts[0].value };
    return { type: 'interp', path: parts[0].value, raw, line: t.line };
  }

  function parseNodes(stopKinds, openLine, openWhat) {
    const nodes = [];
    while (pos < tokens.length) {
      const t = tokens[pos];
      if (t.type === 'text') { nodes.push({ type: 'text', value: t.value }); pos++; continue; }
      const kind = classifyTag(t.content);
      if (stopKinds.includes(kind)) return nodes;
      pos++;
      if (kind === 'comment') continue;
      if (kind === 'style') {
        const styles = t.content.slice(7).trim().split(/\s+/).filter(Boolean);
        nodes.push({ type: 'style', styles, line: t.line });
        continue;
      }
      if (kind === 'interp') { nodes.push(parseInterp(t)); continue; }

      if (kind === 'if') {
        const branches = [];
        branches.push({ expr: parseExpr(t.content.slice(4), t.line), body: parseNodes(['elseif', 'else', 'endif'], t.line, '{{#if}}') });
        let sawElse = false;
        for (;;) {
          if (pos >= tokens.length) throw new Error(`Unclosed {{#if}} opened at line ${t.line}`);
          const bt = tokens[pos];
          const bkind = classifyTag(bt.content);
          if (bkind === 'elseif') {
            if (sawElse) throw new Error(`{{else if}} after {{else}} at line ${bt.line}`);
            pos++;
            branches.push({ expr: parseExpr(bt.content.slice(8), bt.line), body: parseNodes(['elseif', 'else', 'endif'], t.line, '{{#if}}') });
          } else if (bkind === 'else') {
            if (sawElse) throw new Error(`Duplicate {{else}} at line ${bt.line}`);
            sawElse = true;
            pos++;
            branches.push({ expr: null, body: parseNodes(['elseif', 'else', 'endif'], t.line, '{{#if}}') });
          } else { // endif
            pos++;
            break;
          }
        }
        nodes.push({ type: 'if', branches, line: t.line });
        continue;
      }

      if (kind === 'each') {
        const path = t.content.slice(6).trim();
        if (!path) throw new Error(`{{#each}} without a path at line ${t.line}`);
        const body = parseNodes(['endeach'], t.line, '{{#each}}');
        if (pos >= tokens.length) throw new Error(`Unclosed {{#each}} opened at line ${t.line}`);
        pos++; // consume {{/each}}
        nodes.push({ type: 'each', path, body, line: t.line });
        continue;
      }

      // stray else / endif / endeach outside their block
      throw new Error(`Unexpected {{${t.content}}} at line ${t.line}${openWhat ? ` (inside ${openWhat} from line ${openLine})` : ''}`);
    }
    if (stopKinds.length) throw new Error(`Unclosed ${openWhat} opened at line ${openLine}`);
    return nodes;
  }

  return parseNodes([], 0, null);
}

// ─── Evaluation ──────────────────────────────────────────────────────────────

/** has()-semantics: null/undefined/''/false and the string 'false' are falsy. */
function truthy(v) {
  return v !== null && v !== undefined && v !== '' && v !== false && v !== 'false';
}

function walkPath(obj, segs) {
  let cur = obj;
  for (const s of segs) {
    if (cur === null || cur === undefined) return undefined;
    cur = cur[s];
  }
  return cur;
}

/**
 * Resolve a dotted path against the scope stack.
 * scopes[0] is always { item: rootContext }; {{#each}} pushes { item, meta }.
 */
function resolvePath(path, scopes) {
  if (path === '.' || path === 'this') return scopes[scopes.length - 1].item;
  let segs = path.split('.');
  if (segs[0] === 'this') {
    return walkPath(scopes[scopes.length - 1].item, segs.slice(1));
  }
  if (segs[0].startsWith('@')) {
    for (let i = scopes.length - 1; i >= 0; i--) {
      if (scopes[i].meta && segs[0] in scopes[i].meta) return scopes[i].meta[segs[0]];
    }
    return undefined;
  }
  for (let i = scopes.length - 1; i >= 0; i--) {
    const item = scopes[i].item;
    if (item !== null && typeof item === 'object' && segs[0] in item) return walkPath(item, segs);
  }
  return undefined;
}

function evalValue(node, scopes) {
  if (node.op === 'lit' || node.op === 'num') return node.value;
  return resolvePath(node.value, scopes);
}

function looseEquals(l, r) {
  return String(l === null || l === undefined ? '' : l) === String(r === null || r === undefined ? '' : r);
}

function evalExpr(node, scopes) {
  switch (node.op) {
    case 'truthy': return truthy(evalValue(node.operand, scopes));
    case 'not': return !evalExpr(node.operand, scopes);
    case 'and': return evalExpr(node.left, scopes) && evalExpr(node.right, scopes);
    case 'or': return evalExpr(node.left, scopes) || evalExpr(node.right, scopes);
    case '==': return looseEquals(evalValue(node.left, scopes), evalValue(node.right, scopes));
    case '!=': return !looseEquals(evalValue(node.left, scopes), evalValue(node.right, scopes));
    case '>': return Number(evalValue(node.left, scopes)) > Number(evalValue(node.right, scopes));
    case '<': return Number(evalValue(node.left, scopes)) < Number(evalValue(node.right, scopes));
    case '>=': return Number(evalValue(node.left, scopes)) >= Number(evalValue(node.right, scopes));
    case '<=': return Number(evalValue(node.left, scopes)) <= Number(evalValue(node.right, scopes));
    default: throw new Error(`Unknown expression op "${node.op}"`);
  }
}

// ─── Renderer ────────────────────────────────────────────────────────────────

function formatValue(v, raw) {
  if (v === null || v === undefined || v === '') return raw ? '' : FALLBACK;
  return String(v);
}

/**
 * Shared builder used by both renderDocument and renderDocumentWithStyles.
 * sb = { text: string, styleEvents: Array<{charOffset, styles}> }
 * styleEvents is only populated when sb is shared (renderDocumentWithStyles).
 */
function renderNodesInto(nodes, scopes, sb) {
  for (const n of nodes) {
    switch (n.type) {
      case 'text':
        sb.text += n.value;
        break;
      case 'style':
        sb.styleEvents.push({ charOffset: sb.text.length, styles: n.styles });
        break;
      case 'interp':
        sb.text += formatValue(resolvePath(n.path, scopes), n.raw);
        break;
      case 'helper': {
        const args = n.args.map((a) => evalValue(a, scopes));
        const r = HELPERS[n.name](...args);
        sb.text += r === null || r === undefined ? '' : String(r);
        break;
      }
      case 'if':
        for (const b of n.branches) {
          if (b.expr === null || evalExpr(b.expr, scopes)) { renderNodesInto(b.body, scopes, sb); break; }
        }
        break;
      case 'each': {
        const arr = resolvePath(n.path, scopes);
        if (Array.isArray(arr)) {
          arr.forEach((item, i) => {
            scopes.push({
              item,
              meta: { '@index': i, '@index1': i + 1, '@first': i === 0, '@last': i === arr.length - 1 },
            });
            renderNodesInto(n.body, scopes, sb);
            scopes.pop();
          });
        }
        break;
      }
      default:
        throw new Error(`Unknown node type "${n.type}"`);
    }
  }
}

/** Main entry: template string + context → document string. */
function renderDocument(template, context) {
  const ast = parseTemplate(template);
  const sb = { text: '', styleEvents: [] };
  renderNodesInto(ast, [{ item: context, meta: null }], sb);
  return sb.text;
}

/**
 * Like renderDocument but also returns styleHints:
 *   { text: string, styleHints: { [paraIdx]: string[] } }
 * paraIdx is the 0-based paragraph index in the output text (split by '\n').
 * A {{!style: center bold}} before a line means that line's paragraph has those styles.
 * Used by the typography phase-2 pipeline to build Google Docs batchUpdate requests.
 */
function renderDocumentWithStyles(template, context) {
  const ast = parseTemplate(template);
  const sb = { text: '', styleEvents: [] };
  renderNodesInto(ast, [{ item: context, meta: null }], sb);

  const styleHints = {};
  for (const { charOffset, styles } of sb.styleEvents) {
    const paraIdx = sb.text.slice(0, charOffset).split('\n').length - 1;
    styleHints[paraIdx] = styles;
  }
  return { text: sb.text, styleHints };
}

// ─── Helpers (legally-critical logic — written & tested ONCE, shared) ────────

const MONTHS = [
  'січня', 'лютого', 'березня', 'квітня', 'травня', 'червня',
  'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня',
];

/**
 * Registry — slow-changing legal constants (прожитковий мінімум, 2026).
 * SSoT for amounts that drift yearly; template/helpers read this, never hardcode
 * (alimony-change §3.3/§3.4, research 2026-06-15, ярус-3 sign-off pending Olga).
 */
const REGISTRY = {
  pm_able_bodied_2026: 3328,
  pm_child_under6_2026: 2817,
  pm_child_6to18_2026: 3512,
};

const HELPERS = {
  /** ISO date → "20 червня 2015" */
  formatDate(iso) {
    if (!iso) return FALLBACK;
    const d = new Date(iso);
    if (isNaN(d.getTime())) return FALLBACK;
    return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
  },
  /** ISO date → "«20» червня 2015" */
  formatDateQuoted(iso) {
    if (!iso) return '«___» _______ _____';
    const d = new Date(iso);
    if (isNaN(d.getTime())) return '«___» _______ _____';
    return `«${d.getUTCDate()}» ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
  },
  /** gender value ('male'|'female') → word form */
  gender(g, maleWord, femaleWord) {
    return g === 'female' ? femaleWord : maleWord;
  },
  /**
   * 2 forms: plural(n, 'дитина', 'діти') → n===1 ? one : many.
   * 3 forms (Ukrainian): plural(n, 'дитина', 'дитини', 'дітей').
   */
  plural(n, one, few, many) {
    const num = Math.abs(Number(n) || 0);
    if (many === undefined) return num === 1 ? one : few;
    const m10 = num % 10;
    const m100 = num % 100;
    if (m10 === 1 && m100 !== 11) return one;
    if (m10 >= 2 && m10 <= 4 && (m100 < 12 || m100 > 14)) return few;
    return many;
  },
  /** Alimony share per number of children (ст. 183 СК України practice). */
  alimonyFraction(n) {
    const k = Number(n) || 1;
    if (k >= 3) return '1/2';
    if (k === 2) return '1/3';
    return '1/4';
  },
  /** Join args skipping empty values (no separator). */
  concat(...parts) {
    return parts.filter((p) => p !== null && p !== undefined && p !== '').join('');
  },
  /** Value (fallback '________' when empty) with a guaranteed trailing period. */
  ensurePeriod(v) {
    const s = truthy(v) ? String(v) : FALLBACK;
    return s.endsWith('.') ? s : s + '.';
  },
  /** Ukrainian money formatting: 1331.2 → "1 331,20", 24000 → "24 000", 1756 → "1 756". */
  formatMoney(n) {
    if (n === null || n === undefined || n === '') return FALLBACK;
    const num = Number(n);
    if (isNaN(num)) return FALLBACK;
    const rounded = Math.round(num * 100) / 100;
    const [intPart, fracPart] = rounded.toFixed(Number.isInteger(rounded) ? 0 : 2).split('.');
    const withSep = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
    return fracPart ? `${withSep},${fracPart}` : withSep;
  },
};

// ─── Context builder (computed layer shared by all services) ─────────────────

function detectGender(middleName) {
  if (!middleName) return 'male';
  const m = String(middleName).trim();
  if (m.endsWith('івна') || m.endsWith('ївна') || m.endsWith('овна')) return 'female';
  return 'male';
}

function joinName(...parts) {
  const filled = parts.filter((p) => p !== null && p !== undefined && p !== '');
  return filled.length ? filled.join(' ') : FALLBACK;
}

/** "свідоцтво №..." → "свідоцтвом №..." (instrumental after "підтверджується") */
function normalizeCert(certInfo) {
  if (!certInfo) return certInfo;
  if (certInfo.toLowerCase().startsWith('свідоцтво ')) {
    return 'свідоцтвом ' + certInfo.slice('свідоцтво '.length);
  }
  return certInfo;
}

/** "6000" / "6 000" / "6000,50" → number, or null if empty/unparseable. */
function parseMoney(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return isNaN(n) ? null : n;
}

/** "DD.MM.YYYY" (parseChildrenDetails format) → age in full years as of `now`, or null. */
function ageFromBirthDate(birthDate, now = new Date()) {
  const m = /^(\d{1,2})\.(\d{1,2})\.(\d{4})$/.exec(String(birthDate || '').trim());
  if (!m) return null;
  const [, d, mo, y] = m;
  const bd = new Date(Date.UTC(Number(y), Number(mo) - 1, Number(d)));
  let age = now.getUTCFullYear() - bd.getUTCFullYear();
  const monthDiff = now.getUTCMonth() - bd.getUTCMonth();
  if (monthDiff < 0 || (monthDiff === 0 && now.getUTCDate() < bd.getUTCDate())) age--;
  return age;
}

/** 50% ПМ для дитини відповідного віку (alimony-change §3.3), or null if age unknown. */
function pmFloorForAge(age) {
  if (age === null || age === undefined) return null;
  return (age < 6 ? REGISTRY.pm_child_under6_2026 : REGISTRY.pm_child_6to18_2026) / 2;
}

/**
 * children_details (one child per line: "ПІБ, дата, свідоцтво № ... від ...")
 * → [{ raw, name, birthDate, certInfo, certInstrumental, gender }]
 * `raw` keeps the trimmed line as typed (divorce inlines it verbatim).
 */
function parseChildrenDetails(details) {
  if (!details) return [];
  return String(details)
    .split(/\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const parts = line.split(/,\s*/);
      const name = (parts[0] || '').trim();
      const birthDate = (parts[1] || '').trim();
      const certInfo = parts.slice(2).join(', ').trim();
      const nameParts = name.split(/\s+/);
      return {
        raw: line,
        name,
        birthDate,
        certInfo,
        certInstrumental: normalizeCert(certInfo),
        gender: detectGender(nameParts[2]),
      };
    })
    .filter((c) => c.name);
}

/**
 * Build the 3-layer render context: raw answers + ai (with fallbacks) +
 * computed derivations. Computed keys win over same-named answer fields.
 */
function buildContext(answers, ai) {
  const a = answers || {};
  const aiIn = ai || {};

  const plaintiffName = joinName(a.last_name, a.first_name, a.middle_name);
  // The divorce form names the defendant spouse_* (legacy convention) — alias
  // per field so computed values serve both conventions (IMPROVEMENTS #49).
  const defendantName = joinName(
    a.defendant_last_name || a.spouse_last_name,
    a.defendant_first_name || a.spouse_first_name,
    a.defendant_middle_name || a.spouse_middle_name,
  );

  const children = parseChildrenDetails(a.children_details).map((c) => ({
    ...c,
    pmFloor: pmFloorForAge(ageFromBirthDate(c.birthDate)),
  }));

  // alimony-change (§3.3/§3.4): monthly_delta known only when both amounts are
  // fixed sums; price_of_claim/court_fee derive from it, registry-floored.
  const priorAmount = parseMoney(a.prior_alimony_value);
  const requestedAmount = parseMoney(a.requested_alimony_value);
  const monthlyDelta = (a.prior_alimony_type === 'fixed' && a.requested_alimony_type === 'fixed'
    && priorAmount !== null && requestedAmount !== null)
    ? Math.abs(requestedAmount - priorAmount)
    : null;
  const priceOfClaim = monthlyDelta !== null ? monthlyDelta * 12 : null;
  const onePercentOfClaim = priceOfClaim !== null ? Math.round(priceOfClaim * 0.01 * 100) / 100 : null;
  const courtFeeFloor = REGISTRY.pm_able_bodied_2026 * 0.4;
  const courtFee = priceOfClaim !== null ? Math.max(onePercentOfClaim, courtFeeFloor) : null;
  const courtFeeIsFloor = onePercentOfClaim !== null ? onePercentOfClaim <= courtFeeFloor : false;

  const aiSafe = {
    plaintiff_instrumental: aiIn.plaintiff_instrumental || plaintiffName,
    plaintiff_genitive: aiIn.plaintiff_genitive || plaintiffName,
    defendant_instrumental: aiIn.defendant_instrumental || aiIn.spouse_instrumental || defendantName,
    defendant_genitive: aiIn.defendant_genitive || aiIn.spouse_genitive || defendantName,
    marriage_place_locative: aiIn.marriage_place_locative || a.marriage_place || FALLBACK,
    children_genitive: aiIn.children_genitive
      || (children.length ? children.map((c) => `${c.name}, ${c.birthDate} р.н.`).join('; ') : FALLBACK),
    // alimony-change L3 (G3+): case-specific обґрунтування зміни обставин.
    // Empty in G1 (no LLM) → {{#if ai.reasoning}} falls through to the
    // template's generic ст.182 fallback paragraph.
    reasoning: aiIn.reasoning || '',
  };

  return {
    ...a,
    plaintiff_name: plaintiffName,
    defendant_name: defendantName,
    plaintiff_gender: detectGender(a.middle_name),
    defendant_gender: detectGender(a.defendant_middle_name || a.spouse_middle_name),
    children,
    has_children: children.length > 0,
    n_children: children.length || 1,
    first_child_gender: children.length ? children[0].gender : 'male',
    monthly_delta: monthlyDelta,
    price_of_claim: priceOfClaim,
    court_fee: courtFee,
    court_fee_is_floor: courtFeeIsFloor,
    ai: aiSafe,
    // escape hatches for templates whose legacy semantics differ from the
    // computed layer: raw form answers (computed keys shadow e.g. has_children)
    // and the raw AI payload (to branch on "did AI provide X").
    answers: a,
    ai_raw: aiIn,
  };
}

// ── Exports (for Node.js testing; ignored in n8n Code Node) ────────────────

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    renderDocument,
    renderDocumentWithStyles,
    parseTemplate,
    buildContext,
    HELPERS,
    FALLBACK,
    // internals exposed for unit tests
    truthy,
    parseExpr,
    evalExpr,
    detectGender,
    parseChildrenDetails,
    normalizeCert,
    REGISTRY,
    parseMoney,
    ageFromBirthDate,
    pmFloorForAge,
  };
}

// 3b. Checklist validator (mirror: n8n/templates/validate-checklist.js) (#39)
/**
 * validate-checklist.js
 * Deterministic required-clause checklist validator (issue #4 / IMPROVEMENTS #39).
 *
 * No LLM — divorce/alimony render through the deterministic doc-engine
 * (render-document.js), so the only failure mode worth checking is a
 * template/condition bug that silently drops a legally-required clause.
 * Each checklist item is "applicable in this case?" (appliesIf, same
 * expression syntax as {{#if}} in render-document.js) + "does the
 * rendered text satisfy it?" (mustMatchAny — any one pattern is enough,
 * since some obligations are satisfied by either of two formulations,
 * e.g. custody decided vs. explicitly deferred to separate proceedings).
 *
 * n8n entry point (paste into Code Node, after renderDocumentWithStyles):
 *   const result = validateChecklist($json._content, context, svc.required_checklist);
 *   return [{ json: { ...$json, _checklist_result: result } }];
 *
 * Depends on parseExpr/evalExpr from render-document.js being in scope —
 * in the n8n Code Node this file is concatenated right after
 * render-document.js (scripts/sync-build-document-node.mjs), so they're
 * already plain functions in the same script, not require()'d. n8n's Code
 * Node sandbox does not reliably expose a working require(), so this file
 * deliberately has no top-level require/import of its own (see
 * __tests__/validate-checklist.test.js for how tests provide them).
 */

/**
 * @param {string} exprStr - "true" or an expression in render-document.js syntax
 * @param {object} context - same shape as buildContext(answers, ai) output
 */
function evalCondition(exprStr, context) {
  if (exprStr === 'true') return true
  return evalExpr(parseExpr(exprStr, 0), [{ item: context, meta: null }])
}

/**
 * @param {string} renderedText - the final rendered document (_content)
 * @param {object} context - same context object used to render it
 * @param {{items: Array<{id, description, appliesIf, mustMatchAny: string[]}>}} checklist
 * @returns {{ok: boolean, missing: Array, satisfied: Array}}
 */
function validateChecklist(renderedText, context, checklist) {
  const missing = []
  const satisfied = []

  for (const item of (checklist && checklist.items) || []) {
    if (!evalCondition(item.appliesIf, context)) continue

    const ok = item.mustMatchAny.some((pattern) => new RegExp(pattern, 'u').test(renderedText))
    const entry = { id: item.id, description: item.description }
    ;(ok ? satisfied : missing).push(entry)
  }

  return { ok: missing.length === 0, missing, satisfied }
}

// ── Exports (for Node.js testing; ignored in n8n Code Node) ───────────────────

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { validateChecklist, evalCondition }
}

// 4a. Legacy builder (mirror: n8n/templates/divorce-document.js)
/**
 * divorce-document.js
 * n8n Code Node — будує позовну заяву про розірвання шлюбу
 *
 * Вхід:
 *   answers   — об'єкт з відповідями форми (field_id: value)
 *   ai        — об'єкт з відміненими формами від AI:
 *               { plaintiff_instrumental, plaintiff_genitive,
 *                 spouse_instrumental, spouse_genitive,
 *                 marriage_place_locative, children_genitive }
 *
 * Вихід: рядок — готовий текст документа
 *
 * n8n entry point (Code node):
 *   const answers = $('Webhook').item.json.body.answers;
 *   const ai = JSON.parse($('AI Declension').item.json.choices[0].message.content);
 *   const document = buildDivorceDocument(answers, ai);
 *   return [{ json: { document } }];
 */

function buildDivorceDocument(answers, ai) {
  const a = answers;

  // ─── Helpers ────────────────────────────────────────────────────────────────

  const MONTHS = [
    'січня','лютого','березня','квітня','травня','червня',
    'липня','серпня','вересня','жовтня','листопада','грудня'
  ];

  /** ISO дата → "20 червня 2015" */
  function formatDate(iso) {
    if (!iso) return '________';
    const d = new Date(iso);
    return `${d.getUTCDate()} ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
  }

  /** ISO дата → "«20» червня 2015" (для початку речення) */
  function formatDateQuoted(iso) {
    if (!iso) return '«___» _______ _____';
    const d = new Date(iso);
    return `«${d.getUTCDate()}» ${MONTHS[d.getUTCMonth()]} ${d.getUTCFullYear()}`;
  }

  /** Значення поля або прочерк */
  function val(field, fallback = '________') {
    const v = a[field];
    if (v === null || v === undefined || v === '') return fallback;
    return v;
  }

  /** Чи заповнено поле */
  function has(field) {
    const v = a[field];
    return v !== null && v !== undefined && v !== '' && v !== false;
  }

  /** Стать за по батькові */
  function detectGender(middleName) {
    if (!middleName) return 'male';
    const m = String(middleName).trim();
    if (m.endsWith('івна') || m.endsWith('ївна') || m.endsWith('овна')) return 'female';
    return 'male';
  }

  /** Булевий або рядковий "true"/"false" → boolean */
  function isTrue(v) {
    return v === true || v === 'true';
  }

  const REASONS_MAP = {
    'no_common_interests':  'відсутність спільних інтересів',
    'no_understanding':     'відсутність взаєморозуміння',
    'different_views':      'різні погляди на сімейне життя та обов\'язки подружжя',
    'lost_feelings':        'втрата почуття любові та поваги один до одного',
    'incompatibility':      'несумісність характерів',
    'alcohol':              'зловживання алкоголем з боку відповідача',
    'abuse':                'жорстоке поводження з членами сім\'ї з боку відповідача',
    'no_financial_support': 'відсутність фінансової підтримки сім\'ї з боку відповідача',
    'no_child_care':        'ухилення від виховання дітей з боку відповідача',
  };

  /** Масив кодів причин → природній текст ("а також" перед останньою) */
  function formatReasons(reasons) {
    if (!reasons || !reasons.length) return '________';
    const texts = (Array.isArray(reasons) ? reasons : [reasons])
      .map(r => REASONS_MAP[r] || r)
      .filter(Boolean);
    if (texts.length === 0) return '________';
    if (texts.length === 1) return texts[0];
    const last = texts.pop();
    return texts.join(', ') + ', а також ' + last;
  }

  /** Частка аліментів залежно від кількості дітей */
  function alimonyFraction(n) {
    if (n >= 3) return '1/2 (50%)';
    if (n === 2) return '1/3 (33%)';
    return '1/4 (25%)';
  }

  /** Кількість дітей з рядка children_details (один запис на рядок) */
  function countChildren(details) {
    if (!details) return 1;
    const lines = String(details).split(/\n/).filter(l => l.trim());
    return Math.max(1, lines.length);
  }

  /** "дитиною" / "дітьми" */
  function childWord(n) {
    return n === 1 ? 'дитиною' : 'дітьми';
  }

  /** Parse children_details → масив рядків */
  function parseChildren(details) {
    if (!details) return [];
    return String(details).split(/\n/).map(l => l.trim()).filter(Boolean);
  }

  /** Масив дітей → нумерований список з "р.н." для вбудовування в речення */
  function inlineChildren(details) {
    const kids = parseChildren(details);
    if (kids.length === 0) return '________';
    if (kids.length === 1) return `${kids[0]} р.н.`;
    return kids.map((k, i) => `${i + 1}) ${k} р.н.`).join('; ');
  }

  // ─── Базові дані ─────────────────────────────────────────────────────────────

  const plaintiffName = [val('last_name'), val('first_name'), val('middle_name')]
    .filter(s => s !== '________').join(' ') || '________';
  const spouseName = [val('spouse_last_name'), val('spouse_first_name'), val('spouse_middle_name')]
    .filter(s => s !== '________').join(' ') || '________';

  const isFemale      = detectGender(a.middle_name)       === 'female';
  const spouseIsFemale = detectGender(a.spouse_middle_name) === 'female';

  const plaintiffInstrumental  = (ai && ai.plaintiff_instrumental)                               || plaintiffName;
  const plaintiffGenitive      = (ai && ai.plaintiff_genitive)                                  || plaintiffName;
  // Accept both defendant_* (unified) and legacy spouse_* keys
  const spouseInstrumental     = (ai && (ai.defendant_instrumental || ai.spouse_instrumental))  || spouseName;
  const spouseGenitive         = (ai && (ai.defendant_genitive     || ai.spouse_genitive))      || spouseName;
  const marriagePlaceLocative  = (ai && ai.marriage_place_locative)                             || val('marriage_place');
  const childrenGenitive       = (ai && ai.children_genitive)                                   || inlineChildren(a.children_details);

  // ─── ШАПКА ───────────────────────────────────────────────────────────────────

  let doc = '';

  doc += 'До суду за місцем проживання відповідача\n';
  doc += '(Знайти ваш суд: https://court.gov.ua/)\n\n';

  // Позивач
  doc += `Позивач: ${plaintiffName}\n`;
  doc += `Зареєстроване місце проживання: ${val('registered_address')}\n`;
  if (!isTrue(a.same_actual_address) && has('actual_address')) {
    doc += `Фактичне місце проживання: ${a.actual_address}\n`;
  }
  if (!isTrue(a.has_no_ipn) && has('tax_number')) {
    doc += `(реєстраційний номер облікової картки платника податків (ІПН): ${a.tax_number})\n`;
  } else if (isTrue(a.has_no_ipn) && has('passport_series')) {
    doc += `(серія та номер паспорта: ${a.passport_series})\n`;
  }
  if (has('plaintiff_phone')) doc += `Тел.: ${a.plaintiff_phone}\n`;
  if (has('plaintiff_email')) doc += `Адреса електронної пошти: ${a.plaintiff_email}\n`;
  doc += (a.plaintiff_official_email === 'present')
    ? 'Офіційна електронна адреса: наявна в ЄСІТС\n'
    : 'Офіційна електронна адреса — відсутня\n';

  doc += '\n';

  // Відповідач
  doc += `Відповідач: ${spouseName}\n`;
  if (has('spouse_registered_address')) {
    doc += `Зареєстроване місце проживання: ${a.spouse_registered_address}\n`;
  }
  if (a.spouse_actual_address_known === 'different' && has('spouse_actual_address')) {
    doc += `Фактичне місце проживання: ${a.spouse_actual_address}\n`;
  } else if (a.spouse_actual_address_known === 'unknown') {
    doc += 'Фактичне місце проживання невідоме\n';
  }
  if (!isTrue(a.spouse_has_no_ipn) && has('spouse_tax_number')) {
    doc += `(ІПН: ${a.spouse_tax_number})\n`;
  } else if (isTrue(a.spouse_has_no_ipn) && has('spouse_passport_series')) {
    doc += `(серія та номер паспорта: ${a.spouse_passport_series})\n`;
  }
  if (has('spouse_phone')) doc += `Тел.: ${a.spouse_phone}\n`;
  if (has('spouse_email')) doc += `Адреса електронної пошти: ${a.spouse_email}\n`;
  if (a.spouse_official_email === 'present') {
    doc += 'Офіційна електронна адреса: наявна в ЄСІТС\n';
  } else if (a.spouse_official_email === 'unknown') {
    doc += 'Офіційна електронна адреса — невідома\n';
  } else {
    doc += 'Офіційна електронна адреса — відсутня\n';
  }

  // ─── ЗАГОЛОВОК ───────────────────────────────────────────────────────────────

  doc += '\n\nПОЗОВНА ЗАЯВА\nпро розірвання шлюбу\n\n\n';

  // ─── ФАКТИЧНА ЧАСТИНА ────────────────────────────────────────────────────────

  const marriageDateQuoted = formatDateQuoted(a.marriage_date);
  const marriageVerb = isFemale ? 'зареєструвала' : 'зареєстрував';
  const actNum = has('marriage_act_number') ? `актовий запис № ${a.marriage_act_number}` : 'актовий запис № ________';
  let marriageCert = '';
  if (has('marriage_cert_series')) {
    marriageCert = ` (копія свідоцтва про шлюб Серії ${a.marriage_cert_series}`;
    if (has('marriage_cert_date')) {
      marriageCert += ` від ${formatDate(a.marriage_cert_date)} року`;
    }
    marriageCert += ')';
  }

  doc += `${marriageDateQuoted} року я, ${plaintiffName} (надалі за текстом – Позивач) ${marriageVerb} шлюб із ${spouseInstrumental} у ${marriagePlaceLocative}, ${actNum}${marriageCert}.\n\n`;

  // Згода відповідача
  if (isTrue(a.spouse_consents)) {
    doc += `Відповідач ${spouseIsFemale ? 'згодна' : 'згоден'} на розірвання шлюбу.\n\n`;
  } else {
    doc += 'Відповідач не дає згоди на розірвання шлюбу.\n\n';
  }

  // Діти
  if (isTrue(a.has_children)) {
    if (has('children_details')) {
      const childrenText = inlineChildren(a.children_details);
      const period = childrenText.endsWith('.') ? '' : '.';
      doc += `Від даного шлюбу у сторін є спільні неповнолітні діти: ${childrenText}${period}\n`;
    } else {
      doc += 'Від даного шлюбу у сторін є спільні неповнолітні діти: ________ (ПІБ та дати народження).\n';
    }
    if (a.children_live_with === 'plaintiff')        doc += 'Діти проживають з позивачем.\n';
    else if (a.children_live_with === 'defendant')   doc += 'Діти проживають з відповідачем.\n';
    else if (a.children_live_with === 'both')        doc += 'Діти проживають частково з кожним із батьків.\n';
    doc += '\n';
  } else {
    doc += 'Від даного шлюбу спільних дітей у сторін немає.\n\n';
  }

  // ─── ПРАВОВЕ ОБҐРУНТУВАННЯ ───────────────────────────────────────────────────

  doc += 'Відповідно до ч.3 ст.105 СК України шлюб припиняється внаслідок його розірвання за позовом одного з подружжя на підставі рішення суду.\n\n';
  doc += 'Розірвання шлюбу судом відбувається за позовом одного з подружжя відповідно до ст.110 СК України.\n\n';
  doc += 'Відповідно до ст.112 Сімейного кодексу України суд постановляє рішення про розірвання шлюбу, якщо буде встановлено, що подальше спільне життя подружжя і збереження шлюбу суперечило б інтересам одного з них, інтересам їхніх дітей, що мають істотне значення.\n\n';

  const reasonsText = formatReasons(a.divorce_reasons);
  doc += `Підставами для розірвання шлюбу є: ${reasonsText}.\n\n`;

  doc += (a.joint_household === 'yes')
    ? 'З відповідачем продовжуємо вести спільне господарство.\n\n'
    : 'З відповідачем спільного господарства не ведемо.\n\n';

  doc += 'З урахуванням викладеного, вважаю, що подружні відносини між мною та відповідачем фактично припинилися. Подальше спільне життя та збереження шлюбу суперечить моїм інтересам, у зв\'язку з чим наполягаю на його розірванні.\n\n';

  // Спір про дітей
  if (isTrue(a.has_children)) {
    if (a.children_dispute === 'separate') {
      doc += 'Спір щодо місця проживання та виховання дітей є, але буде вирішуватися в окремому провадженні.\n\n';
    } else {
      doc += 'Спір щодо місця проживання та виховання дітей відсутній.\n\n';
    }
  }

  // Спільне майно
  if (isTrue(a.has_joint_property)) {
    if (a.property_dispute === 'separate') {
      doc += 'За час шлюбу сторонами набуто спільне майно. Спір щодо поділу буде вирішуватися в окремому провадженні.\n\n';
    } else {
      const propDetails = has('property_details') ? a.property_details : '________';
      const propEnd = propDetails.endsWith('.') ? '' : '.';
      doc += `За час шлюбу сторонами набуто спільне майно: ${propDetails}${propEnd}\n`;
      doc += `Позивач просить визнати за ${isFemale ? 'нею' : 'ним'} право на 1/2 частку зазначеного майна.\n\n`;
    }
  }

  // Боргові зобов'язання
  if (isTrue(a.debt_claim)) {
    const debtDetails = has('debt_details') ? a.debt_details : '________';
    const debtEnd = debtDetails.endsWith('.') ? '' : '.';
    doc += `Між сторонами є спільні боргові зобов'язання: ${debtDetails}${debtEnd} Відповідно до ст.65 Сімейного кодексу України, позивач просить розподілити зазначені боргові зобов'язання між сторонами.\n\n`;
  }

  // ─── ПРОЦЕСУАЛЬНІ ВИМОГИ (ст.175 ЦПК, пп.6-10) ──────────────────────────────

  doc += 'Відповідно до ст.27 ЦПК України позови до фізичної особи пред\'являються в суд за зареєстрованим у встановленому законом порядку місцем її проживання або перебування, якщо інше не передбачено законом.\n\n';

  // п.6 — досудове врегулювання
  doc += (a.pretrial_settlement === 'conducted')
    ? 'Згідно з п.6 ч.3 ст.175 ЦПК України повідомляю, що заходи досудового врегулювання спору проводилися (медіація / листування).\n\n'
    : 'Згідно з п.6 ч.3 ст.175 ЦПК України повідомляю, що заходи досудового врегулювання спору не проводилися.\n\n';

  // п.7 — забезпечення доказів
  doc += (a.evidence_preservation === 'conducted')
    ? 'Відповідно до п.7 ч.3 ст.175 ЦПК України повідомляю, що заходи забезпечення доказів або позову здійснювалися.\n\n'
    : 'Відповідно до п.7 ч.3 ст.175 ЦПК України повідомляю, що вжиття заходів забезпечення доказів або позову до подання позовної заяви не здійснювалось.\n\n';

  // п.8 — оригінали документів
  doc += (a.originals_location === 'partial' || a.originals_location === 'defendant')
    ? 'Відповідно до п.8 ч.3 ст.175 ЦПК України повідомляю, що частина оригіналів документів перебуває у відповідача. Прошу суд витребувати їх у встановленому порядку.\n\n'
    : 'Відповідно до п.8 ч.3 ст.175 ЦПК України повідомляю, що у позивача перебувають оригінали письмових або електронних доказів, копії яких додано до заяви.\n\n';

  // п.9 — судовий збір
  doc += (a.court_fee_exempt === 'yes')
    ? 'Згідно з п.9 ч.3 ст.175 ЦПК України повідомляю, що витрати на оплату судового збору відсутні у зв\'язку зі звільненням від його сплати.\n\n'
    : 'Згідно з п.9 ч.3 ст.175 ЦПК України повідомляю, що понесені мною витрати становлять __________ грн. (оплата судового збору), що підтверджується квитанцією.\n\n';

  // п.10 — інший позов
  doc += 'Відповідно до п.10 ч.3 ст.175 ЦПК України підтверджую, що мною не подано іншого позову (позовів) до цього ж відповідача (відповідачів) з тим самим предметом та з тих самих підстав.\n\n';

  // ─── СУДОВИЙ ЗБІР ────────────────────────────────────────────────────────────

  const EXEMPT_REASONS = {
    'disability_1_2':  { article: 'п.1 ч.1 ст.5', status: 'особи з інвалідністю I або II групи' },
    'child_disability':{ article: 'п.2 ч.1 ст.5', status: 'законного представника дитини з інвалідністю' },
    'chornobyl':       { article: 'п.11 ч.1 ст.5', status: 'постраждалого від Чорнобильської катастрофи 1–2 категорії' },
  };

  if (a.court_fee_exempt === 'yes') {
    const info = EXEMPT_REASONS[a.court_fee_exempt_reason] || { article: '________', status: '________' };
    const exemptWord = isFemale ? 'звільнена' : 'звільнений';
    doc += `Від сплати судового збору ${exemptWord} на підставі ${info.article} Закону України «Про судовий збір» у зв'язку з наявністю статусу ${info.status}. Посвідчення №________ від ________ додається.\n\n`;
  } else {
    doc += 'Судовий збір сплачений мною в повному обсязі на підставі пп.3 п.1 ч.2 ст.4 Закону України «Про судовий збір».\n\n';
  }

  // ─── ПРОШУ ───────────────────────────────────────────────────────────────────

  doc += 'На підставі вищевикладеного та керуючись ст.ст.105, 110, 112 Сімейного Кодексу України, ст.ст.175, 187, 274 ЦПК України,—\n\n';
  doc += 'П Р О Ш У :\n\n';

  let n = 1;

  // 1. Тип провадження
  doc += (a.simplified_proceedings === 'no')
    ? `${n++}. Відкрити провадження та призначити справу до розгляду в порядку загального позовного провадження.\n\n`
    : `${n++}. Відкрити провадження та призначити справу до розгляду в спрощеному позовному провадженні.\n\n`;

  // 2. Розірвати шлюб
  const birthText       = has('birth_date')       ? `${formatDate(a.birth_date)} року народження`       : 'року народження ________';
  const spouseBirthText = has('spouse_birth_date') ? `${formatDate(a.spouse_birth_date)} року народження` : '________ року народження';
  const marriageDateText = has('marriage_date')    ? `${formatDate(a.marriage_date)} року`               : '________ року';
  const actNumShort = has('marriage_act_number') ? a.marriage_act_number : '________';

  doc += `${n++}. Розірвати шлюб, укладений між мною, ${plaintiffInstrumental}, ${birthText}, та ${spouseInstrumental}, ${spouseBirthText}, зареєстрований ${marriageDateText} у ${marriagePlaceLocative}, актовий запис № ${actNumShort}.\n\n`;

  // 3. Прізвище
  if (a.surname_after_divorce === 'maiden' && has('maiden_name')) {
    doc += `${n++}. Після розірвання шлюбу повернути дошлюбне прізвище – ${a.maiden_name}.\n\n`;
  } else {
    doc += `${n++}. Після розірвання шлюбу залишити прізвище – ${val('last_name')}.\n\n`;
  }

  // 4. Судові витрати
  doc += (a.court_costs_on === 'plaintiff')
    ? `${n++}. Судові витрати по сплаті судового збору залишити за позивачем.\n\n`
    : `${n++}. Судові витрати по сплаті судового збору покласти на відповідача.\n\n`;

  // 5. Місце проживання дітей (якщо є і спір не окремо)
  if (isTrue(a.has_children) && a.children_dispute !== 'separate') {
    const childrenNamesGen = childrenGenitive || '________';
    let livingWith = '________';
    if (a.children_live_with === 'plaintiff')      livingWith = 'позивачем';
    else if (a.children_live_with === 'defendant') livingWith = 'відповідачем';
    doc += `${n++}. Визначити місце проживання ${childrenNamesGen} з ${livingWith}.\n\n`;
  }

  // Аліменти
  if (isTrue(a.alimony_claim)) {
    const nChildren = countChildren(a.children_details);
    const childrenNamesGen = childrenGenitive || '________';
    const cWord = childWord(nChildren);
    let alimonyLine = `${n++}. Стягнути з відповідача, ${spouseGenitive}, аліменти на утримання ${childrenNamesGen} `;
    if (a.alimony_amount === 'percent') {
      alimonyLine += `у розмірі ${alimonyFraction(nChildren)} частини від заробітку та/або іншого доходу щомісячно до досягнення ${cWord} повноліття.\n\n`;
    } else if (a.alimony_amount === 'fixed') {
      alimonyLine += `у твердій грошовій сумі в розмірі __________ грн. щомісячно до досягнення ${cWord} повноліття.\n\n`;
    } else if (a.alimony_amount === 'mixed') {
      alimonyLine += `у розмірі ${alimonyFraction(nChildren)} частини від заробітку та/або іншого доходу, але не менше __________ грн. щомісячно до досягнення ${cWord} повноліття.\n\n`;
    } else {
      alimonyLine += `у розмірі __________ щомісячно до досягнення ${cWord} повноліття.\n\n`;
    }
    doc += alimonyLine;
  }

  // Майно (якщо спір не окремо)
  if (isTrue(a.has_joint_property) && a.property_dispute !== 'separate') {
    const propDetails = has('property_details') ? a.property_details : '________';
    const pe = propDetails.endsWith('.') ? '' : '.';
    doc += `${n++}. Визнати за позивачем право на 1/2 частку спільного майна подружжя, а саме: ${propDetails}${pe}\n\n`;
  }

  // Борги
  if (isTrue(a.debt_claim)) {
    const debtDetails = has('debt_details') ? a.debt_details : '________';
    const de = debtDetails.endsWith('.') ? '' : '.';
    doc += `${n++}. Розподілити між сторонами спільні боргові зобов'язання: ${debtDetails}${de}\n\n`;
  }

  // ─── ДОДАТКИ ─────────────────────────────────────────────────────────────────

  doc += 'Додатки:\n';
  if (a.court_fee_exempt === 'yes') {
    doc += '- копія посвідчення про право на звільнення від судового збору — 2 примірники;\n';
  } else {
    doc += '- квитанція про сплату судового збору (оригінал для суду, копія — відповідачу);\n';
  }
  doc += '- свідоцтво про шлюб (оригінал для суду, копія — відповідачу);\n';
  doc += '- копія паспорта та РНОКПП позивача — 2 примірники;\n';
  if (isTrue(a.has_children)) {
    doc += '- копія/копії свідоцтва/свідоцтв про народження дитини/дітей — по 2 примірники;\n';
  }
  if (isTrue(a.has_joint_property)) {
    doc += '- документи, що підтверджують право власності на спільне майно — по 2 примірники;\n';
  }
  if (isTrue(a.debt_claim)) {
    doc += '- копії документів щодо боргових зобов\'язань (кредитні договори тощо) — по 2 примірники;\n';
  }
  doc += '- 1 екземпляр позовної заяви з копіями доданих документів для відповідача по справі.\n';

  // ─── ПІДПИС ──────────────────────────────────────────────────────────────────

  doc += `\n\n«___» _______ 20__ року                                              (підпис)    ${plaintiffName}\n`;

  return doc;
}


